// spec: specs/client-ordering.md §10 · кейс .qa/tests/client-ordering/co-31-cart-total-loading-skeleton.md (+ co-23)
// seed: tests/seed.buyer.spec.ts
// #b82eba (עבר QA 26.10, commit f6b3f8a): пока грузятся цены (rpc/customer_products), вместо суммы — скелет загрузки (.animate-pulse)
//   в той же строке; ни на одном кадре нет «סה״כ משוער ₪0.00» / «סה״כ לתשלום ₪0.00»; после загрузки сумма = сумма строк.
//   Сценарии: (а) перезагрузка /shop → «הוספה לעגלה» → «עגלה»; (б) задержка ответа customer_products 1.5 с — только скелет, затем
//   сумма; (в) добавление из «השלימו את ההזמנה»; (г) «סה״כ לתשלום» на /shop/checkout. Заказ НЕ оформляется.
// Кадры ловит MutationObserver (init script — с самого начала загрузки страницы). Задержка — page.route → route.continue() после
//   паузы (эмуляция медленной сети, ответ не подменяется).
// Корзина buyer общая → @data, serial; не параллельно с cart-checkout / order-lifecycle / inventory-lifecycle / cart-remove-no-flash.
//   beforeAll — снимок корзины и очистка; afterAll — очистка и возврат снимка (чужие товары, если были, возвращаются).
// Товары берутся из каталога клиента с ценой ≠ ₪0.00 (у клиента test есть товары с ценой ₪0.00 — например «פינלנדיה 200 מ"ל»).
import { test, expect, Page } from '@playwright/test';
import { auth, emptyCart } from '../orders/_qa-order';
import { cartSnapshot, restoreCartIn, CartLine } from './_cart-snapshot';

test.use({ storageState: auth('buyer'), viewport: { width: 1280, height: 900 } });
test.describe.configure({ mode: 'serial' });

let snap: CartLine[] | undefined;
const PRICES = /supabase\.co\/rest\/v1\/rpc\/customer_products/;
const LABELS = ['סה״כ משוער', 'סה״כ לתשלום'];

type Frame = { label: string; amount: string; pulse: boolean; url: string };

/** MutationObserver на строке суммы — с начала каждой загрузки страницы. */
async function installRecorder(page: Page) {
  await page.addInitScript((labels: string[]) => {
    const w = window as unknown as { __frames: unknown[] };
    w.__frames = [];
    const snap = () => {
      for (const label of labels) {
        const lab = [...document.querySelectorAll('p,span,div,dt')].find((e) => e.children.length === 0 && (e.textContent || '').trim() === label);
        if (!lab) continue;
        const row = lab.parentElement!;
        const amount = ((row.textContent || '').match(/₪[\d,]+\.\d\d/) || [''])[0];
        w.__frames.push({ label, amount, pulse: !!row.querySelector('.animate-pulse'), url: location.pathname });
      }
    };
    const start = () => { snap(); new MutationObserver(snap).observe(document.documentElement, { childList: true, subtree: true, characterData: true, attributes: true }); };
    if (document.documentElement) start(); else document.addEventListener('DOMContentLoaded', start);
  }, LABELS);
}

const frames = (page: Page) => page.evaluate(() => (window as unknown as { __frames: Frame[] }).__frames);
const resetFrames = (page: Page) => page.evaluate(() => { (window as unknown as { __frames: Frame[] }).__frames = []; });

/** Проверка записанных кадров: нет ₪0.00; в каждом кадре либо сумма, либо скелет. */
function expectNoZero(f: Frame[], label: string, tag: string) {
  const fl = f.filter((x) => x.label === label);
  expect(fl.length, `${tag}: кадры «${label}» записаны`).toBeGreaterThan(0);
  expect(fl.filter((x) => x.amount === '₪0.00'), `${tag}: ни одного кадра «${label} ₪0.00»`).toEqual([]);
  expect(fl.filter((x) => !x.amount && !x.pulse), `${tag}: без суммы — только скелет`).toEqual([]);
  return fl;
}

const cents = (s: string) => Math.round(Number(s.replace(/[₪,]/g, '')) * 100);
const fmt = (c: number) => '₪' + (c / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const sumRow = (page: Page, label: string) => page.getByText(label, { exact: true }).locator('..');
const removeBtns = (page: Page) => page.getByRole('button', { name: /^הסרה מהעגלה — / });

/** Сумма строк корзины (цена в карточке строки; все строки по 1 шт.). */
async function linesTotal(page: Page) {
  const prices = await removeBtns(page).evaluateAll((btns) => btns.map((b) => {
    // карточка строки = самый широкий предок, в котором ровно одна кнопка «הסרה מהעגלה»
    let card: Element = b;
    while (card.parentElement && card.parentElement.querySelectorAll('button[aria-label^="הסרה מהעגלה"]').length === 1) card = card.parentElement;
    const p = [...card.querySelectorAll('[dir="ltr"]')].map((e) => (e.textContent || '').trim()).find((t) => /^₪[\d,]+\.\d\d$/.test(t));
    return p || '';
  }));
  expect(prices.filter((p) => !p), 'у каждой строки есть цена').toEqual([]);
  return prices.reduce((s, p) => s + cents(p), 0);
}

/** Сумма в «סה״כ משוער» = сумма строк, «פריטים בעגלה» = число строк. */
async function expectCartTotalCorrect(page: Page, lines: number) {
  await expect(removeBtns(page)).toHaveCount(lines, { timeout: 20_000 });
  const total = fmt(await linesTotal(page));
  await expect(sumRow(page, 'סה״כ משוער'), `«סה״כ משוער» = сумма строк ${total}`).toContainText(total, { timeout: 20_000 });
  await expect(sumRow(page, 'סה״כ משוער').locator('.animate-pulse'), 'скелет суммы исчез').toHaveCount(0);
  await expect(sumRow(page, 'פריטים בעגלה')).toContainText(String(lines));
  return total;
}

/** /shop после перезагрузки → «הוספה לעגלה» первого товара с ценой ≠ ₪0.00. Возвращает имя товара. */
async function addFromShop(page: Page) {
  await page.goto('/shop');
  await page.reload();
  const add = page.getByRole('button', { name: /^הוספה לעגלה — / });
  await expect(add.first()).toBeVisible({ timeout: 30_000 });
  const name = await page.evaluate(() => {
    for (const art of document.querySelectorAll('article')) {
      const b = art.querySelector('button[aria-label^="הוספה לעגלה — "]') as HTMLButtonElement | null;
      const price = ((art.textContent || '').match(/₪[\d,]+\.\d\d/) || [''])[0];
      if (b && !b.disabled && price && price !== '₪0.00') return b.getAttribute('aria-label')!.replace('הוספה לעגלה — ', '');
    }
    return null;
  });
  expect(name, 'в каталоге есть товар с ценой ≠ ₪0.00').not.toBeNull();
  const added = page.waitForResponse((r) => r.url().includes('cart_set_item'));
  await page.getByRole('button', { name: `הוספה לעגלה — ${name}`, exact: true }).first().click();
  await added;
  return name!;
}

const openCartFromNav = async (page: Page) => {
  await page.getByRole('link', { name: /^\d*\s*עגלה/ }).last().click();
  await expect(page).toHaveURL(/\/shop\/cart/);
  await expect(page.getByRole('heading', { name: 'העגלה שלי' })).toBeVisible({ timeout: 30_000 });
};

const delayPrices = (page: Page) => page.route(PRICES, async (route) => {
  await new Promise((r) => setTimeout(r, 1500)); // эмуляция медленной сети, не пауза теста
  await route.continue();
});

test.describe('client-ordering — עגלה: שלד טעינה במקום «₪0.00» בסה״כ (#b82eba)', () => {
  test.beforeAll(async ({ browser }) => {
    test.setTimeout(120_000);
    const ctx = await browser.newContext({ storageState: auth('buyer'), locale: 'he-IL', viewport: { width: 1280, height: 900 } });
    const page = await ctx.newPage();
    snap = await cartSnapshot(page);
    await emptyCart(page);
    await ctx.close();
  });

  test.afterAll(async ({ browser }) => {
    test.setTimeout(240_000);
    const ctx = await browser.newContext({ storageState: auth('buyer'), locale: 'he-IL', viewport: { width: 1280, height: 900 } });
    await emptyCart(await ctx.newPage()).catch(() => {});
    await ctx.close();
    await restoreCartIn(browser, snap);
  });

  test('רענון /shop ← «הוספה לעגלה» ← «עגלה»: אין «סה״כ משוער ₪0.00» בשום פריים, אחר כך הסכום = סכום השורות #b82eba @desktop @orders @data', async ({ page }) => {
    test.setTimeout(120_000);
    await installRecorder(page);
    await emptyCart(page);
    await addFromShop(page);
    await resetFrames(page);
    await openCartFromNav(page);
    const total = await expectCartTotalCorrect(page, 1);
    const fl = expectNoZero(await frames(page), 'סה״כ משוער', 'открытие корзины');
    expect(fl[fl.length - 1].amount, 'последний кадр — верная сумма').toBe(total);
  });

  test('תגובת customer_products מתעכבת 1.5 ש׳: רק שלד במקום הסכום, אחר כך הסכום הנכון #b82eba @desktop @orders @data', async ({ page }) => {
    test.setTimeout(120_000);
    await installRecorder(page);
    await emptyCart(page);
    await addFromShop(page);
    await delayPrices(page);
    // (1) переход в корзину из нижнего меню
    await resetFrames(page);
    await openCartFromNav(page);
    let total = await expectCartTotalCorrect(page, 1);
    expectNoZero(await frames(page), 'סה״כ משוער', 'меню → корзина, задержка 1.5 с');
    // (2) перезагрузка корзины — первая загрузка цен после старта страницы
    const prices = page.waitForResponse(PRICES, { timeout: 30_000 });
    await page.reload();
    await expect(sumRow(page, 'סה״כ משוער').locator('.animate-pulse'), 'пока цены грузятся — скелет на месте суммы').toBeVisible({ timeout: 20_000 });
    await expect(sumRow(page, 'סה״כ משוער')).not.toContainText('₪');
    await prices;
    total = await expectCartTotalCorrect(page, 1);
    const fl = expectNoZero(await frames(page), 'סה״כ משוער', 'reload корзины, задержка 1.5 с');
    expect(fl.some((x) => x.pulse && !x.amount), 'скелет был показан').toBe(true);
    expect(fl[fl.length - 1].amount, 'последний кадр — верная сумма').toBe(total);
    await page.unroute(PRICES);
  });

  test('הוספה מ«השלימו את ההזמנה» בתוך העגלה: הסכום לא מתאפס ל-₪0.00, אחר כך = סכום 2 השורות #b82eba @desktop @orders @data', async ({ page }) => {
    test.setTimeout(120_000);
    await installRecorder(page);
    await emptyCart(page);
    await addFromShop(page);
    await openCartFromNav(page);
    await expectCartTotalCorrect(page, 1);
    const suggestion = page.getByRole('button', { name: /^הוספה לעגלה — / });
    await expect(suggestion.first(), 'блок «השלימו את ההזמנה»').toBeVisible({ timeout: 20_000 });
    const name = await suggestion.evaluateAll((btns) => {
      const ok = btns.find((b) => !((b.closest('article') ?? b.parentElement)?.textContent || '').includes('₪0.00') && !(b as HTMLButtonElement).disabled);
      return (ok ?? btns[0]).getAttribute('aria-label')!.replace('הוספה לעגלה — ', '');
    });
    await resetFrames(page);
    const added = page.waitForResponse((r) => r.url().includes('cart_set_item'));
    await page.getByRole('button', { name: `הוספה לעגלה — ${name}`, exact: true }).first().click();
    await added;
    const total = await expectCartTotalCorrect(page, 2);
    const fl = expectNoZero(await frames(page), 'סה״כ משוער', 'добавление из «השלימו את ההזמנה»');
    expect(fl[fl.length - 1].amount, 'последний кадр — верная сумма').toBe(total);
  });

  test('«סה״כ לתשלום» במסך ביצוע הזמנה: בלי ₪0.00 (גם בתגובה איטית), שווה לסכום העגלה; ההזמנה לא נשלחת #b82eba @desktop @orders @data', async ({ page }) => {
    test.setTimeout(120_000);
    await installRecorder(page);
    await emptyCart(page);
    await addFromShop(page);
    await openCartFromNav(page);
    const cartTotal = await expectCartTotalCorrect(page, 1);
    await resetFrames(page);
    await page.getByRole('button', { name: 'המשך לביצוע הזמנה' }).click();
    await expect(page).toHaveURL(/\/shop\/checkout/);
    await expect(page.getByRole('heading', { name: 'ביצוע הזמנה' })).toBeVisible({ timeout: 30_000 });
    await expect(sumRow(page, 'סה״כ לתשלום')).toContainText(cartTotal, { timeout: 20_000 });
    expectNoZero(await frames(page), 'סה״כ לתשלום', 'корзина → ביצוע הזמנה');
    // медленный ответ цен при перезагрузке экрана оформления
    await delayPrices(page);
    await page.reload();
    await expect(sumRow(page, 'סה״כ לתשלום')).toContainText(cartTotal, { timeout: 30_000 });
    const fl = expectNoZero(await frames(page), 'סה״כ לתשלום', 'reload ביצוע הזמנה, задержка 1.5 с');
    expect(fl[fl.length - 1].amount, 'последний кадр — сумма корзины').toBe(cartTotal);
    await page.unroute(PRICES);
    await expect(page.getByRole('button', { name: 'שליחת הזמנה' }), 'заказ не отправляем — кнопка на месте').toBeVisible();
  });
});
